/// Isolate numeric tokens, including ranges and signs, within RTL bibliography.
/// Does not reshape or translate scholarly source text.
String libraryBidi(String value, String languageCode) {
  final hasArabic = RegExp(r'[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]').hasMatch(value);
  if (languageCode != 'ar' && !hasArabic) return value;
  return value.replaceAllMapped(
    RegExp(r'\u2066[^\u2069]*\u2069|(?:[≤≥<>]\s*)?[0-9٠-٩۰-۹]+(?:[.,:/–\-][0-9٠-٩۰-۹]+)*\+?'),
    (match) => match[0]!.startsWith('\u2066') ? match[0]! : '\u2066${match[0]}\u2069',
  );
}

String libraryDataLabel(String value, String languageCode) {
  final trimmed = value.trim();
  final key = _libraryDataKeys[trimmed];
  var result = key == null ? trimmed : libraryDictionary[key]![languageCode] ?? trimmed;
  // These are catalogue unit labels, not book titles or author names.
  if (key == null && languageCode != 'id') {
    result = result.replaceAll(RegExp(r'\bJilid\b', caseSensitive: false),
      languageCode == 'ar' ? 'مجلد' : 'volumes');
    result = result.replaceAll('Kitab Fisik', languageCode == 'ar' ? 'كتاب مطبوع' : 'printed books');
  }
  return libraryBidi(result, languageCode);
}

/// Only replace known missing-source sentinels; retain actual titles and names.
String librarySourceLabel(String value, String languageCode) {
  if (value.trim() == 'غير معروف' || value.trim() == 'بدون عنوان') {
    return libraryDataLabel(value, languageCode);
  }
  return value;
}

String libraryCollectionTitle(String key, String fallback, String languageCode) =>
    libraryDictionary['library.collection_$key']?[languageCode] ?? fallback;
